export default function LegoMethodItems() {
  const openDrawer = useMethodLinkInDrawer(paths.beads.method.iron.key);
  
  const selectTarget = useItemCardSelectTarget(paths.beads.method.iron.path());
  
  const { setItemsComponent } = useMenuContext();
  useEffect(() => {
    setItemsComponent([
      { title: 'とび出すと面白い：', items: [
        { title: '丸めて立体', href: '#bend-flat-slide' },
        { title: '積層型', href: '#stacked-type' },
        { title: '面立体構成', href: '#surface-configuration' },
        { title: 'ワイヤー立体', href: '#wire-structure' },
      ]},
      { title: '固めると用途広がる：', items: [
        { title: 'アイロンがけ(サイド熱着)', href: '#iron-pattern-01' },
      ]}
    ]);
  }, []);
  
  return (
    <MethodDrawerContent
      title='アイロンビーズのレシピ集'
      prelude={<Box>
          アイロンビーズの魅力は「自分だけのプラスチック製の小物を作れる」ことだと思います。(一家に一台３Ｄプリンターが置ける時代になったら変わるかもですが)<br/>
          ただ「何をどうすれば良いのか・・・」と悩んじゃうかもしれません。<br/>
          そんな時は "まず真似てみる" から始める方法があります。（"遊び"なので"直ぐに成果を求めない"のがポイントです）<br/>
          <br/>
          ここでは "素(もと)になるレシピ集" として、私が「何かに使えないかな」と色々と試したモノと、その思い付いたキッカケなどを紹介していきます。<br/>
          冒頭で紹介した「何に見える？」の連想ゲーム<AssociationGameRemark withinPortal withinScroll />と合わせて、「こうしたら可愛くできるかも」とか
          身の回りの遊びや装飾などへと、少しずつ広げて頂ければと思います。<br/>
          見てくれた方々が「私だったらこうしよ〜」と、イメージを広げるキッカケとなれたなら、幸いです。
        </Box>}
      >
      <MyMethodMainArea>
        <Detail openDrawer={openDrawer} selectTarget={selectTarget} />
      </MyMethodMainArea>
    </MethodDrawerContent>
  )
}



import { MyMethodMainArea } from '~/ui/layout/MyMain'


type DetailProp = {
  openDrawer: (kind: string, name: string) => () => void;
  selectTarget :SelectTarget;
}
const Detail = memo(function Detail(prop: DetailProp) {
  const { openDrawer, selectTarget } = prop;
  return (
    <>
      <SectionCard title='とび出すと面白い' prelude={<>
        平面をちょっといじってボリュームを出すことで立体にする素(もと)となるレシピ集です。<br/>
        これらを組み合わせたり、アレンジしたりして "ちょっと楽しめる" モノを作っていくイメージ。<br/>
        <br/>
        平面では「ドット(点)を並べて恐竜にみせるにはどうするかな」など、描くことがメインとなりますが、<br/>
        立体になると出来る幅も広がるので、更に面白くなると思います。
        </>}
        >
        <BendFlatSide openDrawer={openDrawer} selectTarget={selectTarget} />
        <StackedType openDrawer={openDrawer} selectTarget={selectTarget} />
        <SurfaceConfiguration openDrawer={openDrawer} selectTarget={selectTarget} />
        <WireStructure openDrawer={openDrawer} selectTarget={selectTarget} />
      </SectionCard>
      <SectionCard title='固めると用途広がる' prelude={<>
        せっかく作った立体作品も、壊れやすいと大事に家で飾るだけになっちゃいがち。<br/>
        固めて丈夫にして、もっと色々な用途で "楽しめる" モノを作っていくイメージです。<br/>
        <br/>
        アイロンビーズと言うこともあって、アイロンを使って丈夫にする方法を紹介します。
        </>}
        >
        <IronPattern01 openDrawer={openDrawer} selectTarget={selectTarget} />
      </SectionCard>
    </>
  )
}, (prop1, prop2) => (prop1.openDrawer === prop2.openDrawer && prop1.selectTarget === prop2.selectTarget))

